# fragment extraction against a decimal-based brute force
def brute(rows, width):
    out = []
    for ri, row in enumerate(rows):
        vals = row['values']
        acts = row['activation']
        n = len(vals)
        if 1514 in vals:
            n = vals.index(1514)
        if n == 0:
            continue
        a = [D(x) for x in acts[:n]]
        mean = sum(a)/D(n)
        sd = (sum((x-mean)**2 for x in a)/D(n)).sqrt()
        high = [x > mean+sd for x in a]
        i = 0
        while i < n:
            if not high[i]:
                i += 1
                continue
            j = i
            while j < n and high[j]:
                j += 1
            if j-i >= 2:
                if j-i <= width:
                    out.append((ri, i, j-i, tuple(vals[i:j]), row['class']))
                else:
                    best = None
                    bs = None
                    for s in range(i, j-width+1):
                        cur = sum(acts[s:s+width])
                        if best is None or cur > best:
                            best = cur
                            bs = s
                    out.append((ri, bs, width, tuple(vals[bs:bs+width]), row['class']))
            i = j
    return out


