# clustering against a pure-python DBSCAN following the contract text
def brute_cluster(frags, classes, eps, ratio):
    en, ed = eps
    rn, rd = ratio
    per_class = {}
    for fid, f in enumerate(frags):
        per_class.setdefault(f[4], []).append(fid)
    groups = {}
    for fid, f in enumerate(frags):
        groups.setdefault((f[4], f[2]), []).append(fid)
    adj = {}
    core = {}
    for (cls, L), ids in groups.items():
        m = len(per_class[cls])
        dmin = max(2, -((-m*rn)//rd))
        for i in ids:
            nb = []
            for j in ids:
                a, b = frags[i][3], frags[j][3]
                total = 0
                anch = 0
                for x, y in zip(a, b):
                    d = abs(x-y)
                    if (x < 1514 < y) or (y < 1514 < x):
                        d += 1000
                    total += d*d
                    if x == y:
                        anch += 1
                if Fraction(total, L)*POW[anch]**2 <= Fraction(en, ed)**2:
                    nb.append(j)
            adj[i] = nb
            core[i] = len(nb) >= dmin
    labels = {}
    clusters = {}
    for i in sorted(adj):
        if not core[i] or i in labels:
            continue
        stack = [i]
        comp = []
        labels[i] = i
        while stack:
            v = stack.pop()
            comp.append(v)
            for w in adj[v]:
                if core[w] and w not in labels:
                    labels[w] = i
                    stack.append(w)
        cid = min(comp)
        for v in comp:
            labels[v] = cid
        clusters.setdefault(cid, {'core': [], 'members': [], 'class': frags[cid][4]})
        clusters[cid]['core'].extend(comp)
    noise = []
    for i in sorted(adj):
        if core[i]:
            continue
        best = None
        for j in adj[i]:
            if core[j]:
                if best is None or labels[j] < best:
                    best = labels[j]
        if best is None:
            noise.append(i)
        else:
            clusters[best]['members'].append(i)
    for cid, c in clusters.items():
        c['members'] = sorted(c['members']+c['core'])
        c['core'] = sorted(c['core'])
    return clusters, sorted(noise)


